 76	/// What the engine found when it looked for a handoff. `Missing` and
 77	/// `Unreadable` are deliberately separate variants: "no session ever wrote
 78	/// one" and "one was written but the engine cannot read it back" call for
 79	/// different operator responses, and collapsing them would hide the
 80	/// second behind the first.
 81	#[derive(Debug, Clone, PartialEq, Eq)]
 82	pub(crate) enum HandoffState {
 83	    Present(CoordinatorHandoff),
 84	    Missing,
 85	    Unreadable(String),
 86	}
 87	
 88	impl HandoffState {
 89	    /// Short label for the engine-audit log.
 90	    pub(crate) fn audit_outcome(&self) -> &'static str {
 91	        match self {
 92	            Self::Present(_) => "present",
 93	            Self::Missing => "missing",
 94	            Self::Unreadable(_) => "unreadable",
 95	        }
 96	    }
 97	}
