 99	/// Why a fresh coordinator session is being created. Rendered into the
100	/// session-start brief so the incoming session can tell the operator what
101	/// ended the previous one — a crash and an operator reset warrant
102	/// different first replies.
103	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
104	pub(crate) enum CoordinatorStartReason {
105	    /// No coordinator record existed: the first session on this engine.
106	    FirstCreation,
107	    /// The recorded tmux session no longer exists (tmux server restart,
108	    /// session killed, or a crash window between intent and creation).
109	    SessionMissing,
110	    /// The tmux session survived but its `claude` process exited — a
111	    /// crash, `/exit`, or a Claude Code update that ended the process.
112	    PaneDead,
113	    /// An explicit UI-confirmed recreate (model mismatch or operator reset,
114	    /// the latter also being how a `claude` update is picked up).
115	    Recreate(CoordinatorRecreateReason),
116	}
117	
118	impl CoordinatorStartReason {
119	    fn describe(self) -> &'static str {
120	        match self {
121	            Self::FirstCreation => "this is the first coordinator session on this engine",
122	            Self::SessionMissing => {
123	                "the previous coordinator's tmux session no longer existed (tmux server restart, session \
124	                 killed, or an engine crash mid-create)"
125	            }
126	            Self::PaneDead => {
127	                "the previous coordinator's claude process exited (a crash, `/exit`, or a Claude Code update \
128	                 ending the process) while its tmux session survived"
129	            }
130	            Self::Recreate(CoordinatorRecreateReason::ModelMismatch) => {
131	                "the operator confirmed replacing the previous coordinator to change its model"
132	            }
133	            Self::Recreate(CoordinatorRecreateReason::OperatorReset) => {
134	                "the operator explicitly reset the coordinator (typically to pick up a Claude Code update or \
135	                 clear context)"
136	            }
137	        }
138	    }
139	
140	    pub(crate) fn audit_label(self) -> &'static str {
141	        match self {
142	            Self::FirstCreation => "first_creation",
143	            Self::SessionMissing => "session_missing",
144	            Self::PaneDead => "pane_dead",
145	            Self::Recreate(CoordinatorRecreateReason::ModelMismatch) => "recreate_model_mismatch",
146	            Self::Recreate(CoordinatorRecreateReason::OperatorReset) => "recreate_operator_reset",
147	        }
148	    }
149	}
