  1	//! `FrontendRequest::GetCoordinatorHandoff` / `SetCoordinatorHandoff`
  2	//! handlers — `boss handoff show` / `boss handoff write`.
  3	//!
  4	//! The coordinator session handoff is the short brief the outgoing
  5	//! coordinator session writes so the next one does not start with zero
  6	//! knowledge of what the operator said; see [`crate::coordinator_handoff`]
  7	//! for the storage, state, and delivery design. These handlers are the
  8	//! write path (the coordinator itself, via the CLI) and the read-back path
  9	//! (`show`, e.g. after context compaction).
 10	//!
 11	//! Both are coordinator-only at the worker-tier gate
 12	//! (`boss_worker_policy::worker_verb_decision`); nothing here is
 13	//! peer-attributed beyond that.
 14	
 15	use super::*;
 16	
 17	use crate::coordinator_handoff::{HandoffState, handoff_view, validate_handoff_body};
 18	
 19	/// Spawn token of the coordinator record that is live now, for stamping
 20	/// a write and for judging `written_by_current_session` on a read.
 21	fn current_spawn_token(work_db: &WorkDb) -> Result<Option<String>, String> {
 22	    work_db
 23	        .coordinator_tmux_record()
 24	        .map(|record| record.map(|record| record.spawn_token))
 25	        .map_err(|err| format!("failed to read the coordinator record: {err:#}"))
 26	}
 27	
 28	pub(super) async fn handle_get_coordinator_handoff(ctx: Dispatch, req: FrontendRequest) {
 29	    let Dispatch {
 30	        work_db,
 31	        sink,
 32	        request_id,
 33	        ..
 34	    } = ctx;
 35	    let FrontendRequest::GetCoordinatorHandoff = req else {
 36	        unreachable!()
 37	    };
 38	    let current = match current_spawn_token(&work_db) {
 39	        Ok(current) => current,
 40	        Err(message) => {
 41	            tracing::error!(%message, "get_coordinator_handoff failed");
 42	            return send_work_error(&sink, &request_id, message);
 43	        }
 44	    };
 45	    match work_db.coordinator_handoff_state() {
 46	        HandoffState::Missing => {
 47	            send_response(
 48	                &sink,
 49	                &request_id,
 50	                FrontendEvent::CoordinatorHandoffResult { handoff: None },
 51	            );
 52	        }
 53	        HandoffState::Present(handoff) => {
 54	            let now = boss_engine_utils::epoch_time::now_epoch_secs();
 55	            send_response(
 56	                &sink,
 57	                &request_id,
 58	                FrontendEvent::CoordinatorHandoffResult {
 59	                    handoff: Some(handoff_view(&handoff, current.as_deref(), now)),
 60	                },
 61	            );
 62	        }
 63	        HandoffState::Unreadable(reason) => {
 64	            // Deliberately an error, not an empty success: "stored but
 65	            // unreadable" must never read as "nothing was handed off".
 66	            tracing::error!(%reason, "get_coordinator_handoff: stored handoff is unreadable");
 67	            send_work_error(&sink, &request_id, reason);
 68	        }
 69	    }
 70	}
 71	
 72	pub(super) async fn handle_set_coordinator_handoff(ctx: Dispatch, req: FrontendRequest) {
 73	    let Dispatch {
 74	        work_db,
 75	        sink,
 76	        request_id,
 77	        ..
 78	    } = ctx;
 79	    let FrontendRequest::SetCoordinatorHandoff { body } = req else {
 80	        unreachable!()
 81	    };
 82	    let body = match validate_handoff_body(&body) {
 83	        Ok(body) => body,
 84	        Err(message) => {
 85	            tracing::warn!(%message, "set_coordinator_handoff rejected");
 86	            return send_work_error(&sink, &request_id, message);
 87	        }
 88	    };
 89	    let current = match current_spawn_token(&work_db) {
 90	        Ok(current) => current,
 91	        Err(message) => {
 92	            tracing::error!(%message, "set_coordinator_handoff failed");
 93	            return send_work_error(&sink, &request_id, message);
 94	        }
 95	    };
 96	    let now = boss_engine_utils::epoch_time::now_epoch_secs();
 97	    let writer = current.as_deref().unwrap_or_default();
 98	    match work_db.set_coordinator_handoff(&body, writer, now) {
 99	        Ok(handoff) => {
100	            crate::audit::record_event(
101	                "coordinator_handoff_written",
102	                &serde_json::json!({
103	                    "bytes": handoff.body.len(),
104	                    "writer_spawn_token": handoff.writer_spawn_token,
105	                    "written_at": handoff.written_at,
106	                }),
107	            );
108	            tracing::info!(
109	                bytes = handoff.body.len(),
110	                writer_spawn_token = %handoff.writer_spawn_token,
111	                "coordinator handoff written"
112	            );
113	            send_response(
114	                &sink,
115	                &request_id,
116	                FrontendEvent::CoordinatorHandoffSet {
117	                    handoff: handoff_view(&handoff, current.as_deref(), now),
118	                },
119	            );
120	        }
121	        Err(err) => {
122	            tracing::error!(?err, "set_coordinator_handoff failed to persist");
123	            send_work_error(
124	                &sink,
125	                &request_id,
126	                format!("failed to persist coordinator handoff: {err:#}"),
127	            );
128	        }
129	    }
130	}

  1	//! `boss handoff write` / `boss handoff show` — the coordinator session
  2	//! handoff.
  3	//!
  4	//! The outgoing coordinator session writes a short brief (operator-stated
  5	//! facts that changed the world, decisions, open threads, prohibitions);
  6	//! the engine stores it as coordinator-private state and hands it to the
  7	//! next fresh coordinator session as that session's first prompt. `show`
  8	//! reads it back at any time (after context compaction, say). Design:
  9	//! `tools/boss/docs/coordinator-session-handoff.md`.
 10	
 11	use boss_protocol::{CoordinatorHandoffView, FrontendEvent, FrontendRequest};
 12	use clap::{Args, Subcommand};
 13	
 14	use crate::{CliError, RunContext, connect_for_work, print_entity, unexpected_event};
 15	
 16	#[derive(Debug, Subcommand)]
 17	pub(crate) enum HandoffCommand {
 18	    /// Replace the stored handoff with the contents of FILE (`-` reads
 19	    /// stdin, so a heredoc works with no scratch file). The engine stamps
 20	    /// the write with the time and the live coordinator session, which is
 21	    /// how the next session judges staleness. Each write replaces the
 22	    /// whole handoff: carry forward what is still true. Blank bodies and
 23	    /// bodies over the engine's cap (16 KiB) are rejected — a handoff is
 24	    /// a brief of operator-stated facts, decisions, open threads, and
 25	    /// prohibitions, not a transcript.
 26	    Write(HandoffWriteArgs),
 27	    /// Print the stored handoff with when it was written, how old it is,
 28	    /// and whether the current coordinator session wrote it. Says
 29	    /// explicitly when none has ever been written; a stored-but-unreadable
 30	    /// handoff is an error, never an empty result.
 31	    Show,
 32	}
 33	
 34	#[derive(Debug, Clone, Args)]
 35	pub(crate) struct HandoffWriteArgs {
 36	    /// Path to the handoff text, or `-` to read it from stdin.
 37	    pub(crate) file: String,
 38	}
 39	
 40	pub(crate) async fn run_handoff_command(command: HandoffCommand, ctx: &RunContext) -> Result<(), CliError> {
 41	    match command {
 42	        HandoffCommand::Write(args) => run_write(ctx, args).await,
 43	        HandoffCommand::Show => run_show(ctx).await,
 44	    }
 45	}
 46	
 47	fn read_body(file: &str) -> Result<String, CliError> {
 48	    if file == "-" {
 49	        let mut body = String::new();
 50	        std::io::Read::read_to_string(&mut std::io::stdin(), &mut body)
 51	            .map_err(|e| CliError::internal(anyhow::anyhow!("read stdin: {e}")))?;
 52	        return Ok(body);
 53	    }
 54	    std::fs::read_to_string(file).map_err(|e| CliError::usage(format!("cannot read handoff file {file}: {e}")))
 55	}
 56	
 57	async fn run_write(ctx: &RunContext, args: HandoffWriteArgs) -> Result<(), CliError> {
 58	    let body = read_body(&args.file)?;
 59	    let mut client = connect_for_work(ctx).await?;
 60	    let handoff: CoordinatorHandoffView = rpc_call!(
 61	        client,
 62	        FrontendRequest::SetCoordinatorHandoff { body },
 63	        "handoff write",
 64	        FrontendEvent::CoordinatorHandoffSet { handoff } => handoff,
 65	    )?;
 66	    print_entity(ctx, &handoff, || {
 67	        println!(
 68	            "Coordinator handoff written: {} bytes at {}.",
 69	            handoff.body.len(),
 70	            handoff.written_at_iso8601
 71	        );
 72	        if !handoff.written_by_current_session {
 73	            println!(
 74	                "note: the engine has no live coordinator session on record, so this handoff is not attributed \
 75	                 to one; the next coordinator session will see it as written by an unknown session."
 76	            );
 77	        }
 78	    })
 79	}
 80	
 81	async fn run_show(ctx: &RunContext) -> Result<(), CliError> {
 82	    let mut client = connect_for_work(ctx).await?;
 83	    let handoff: Option<CoordinatorHandoffView> = rpc_call!(
 84	        client,
 85	        FrontendRequest::GetCoordinatorHandoff,
 86	        "handoff show",
 87	        FrontendEvent::CoordinatorHandoffResult { handoff } => handoff,
 88	    )?;
 89	    print_entity(ctx, &serde_json::json!({ "handoff": handoff }), || match &handoff {
 90	        None => println!(
 91	            "No coordinator handoff is stored: no coordinator session has ever written one. \
 92	             Write one with `boss handoff write -` (stdin) or `boss handoff write <file>`."
 93	        ),
 94	        Some(handoff) => {
 95	            let writer = if handoff.written_by_current_session {
 96	                "this coordinator session".to_owned()
 97	            } else if handoff.writer_spawn_token.is_empty() {
 98	                "an unknown session (no coordinator was on record at write time)".to_owned()
 99	            } else {
100	                format!(
101	                    "an EARLIER coordinator session (spawn token {}); nothing said to the current session is in it",
102	                    handoff.writer_spawn_token
103	                )
104	            };
105	            let age = boss_engine_utils::iso8601::format_elapsed_ago(
106	                handoff.written_at,
107	                handoff.written_at + handoff.age_secs,
108	            )
109	            .unwrap_or_else(|| handoff.written_at_iso8601.clone());
110	            let written =
111	                crate::time_fmt::format_epoch(handoff.written_at, &crate::time_fmt::resolve_display_tz(false));
112	            println!("Written: {written} ({age}) by {writer}");
113	            println!("---");
114	            println!("{}", handoff.body);
115	        }
116	    })
117	}

