301	async fn recreate_after_confirmation_inner(
302	    spawn: &CoordinatorSpawn<'_>,
303	    expected_spawn_token: &str,
304	    reason: CoordinatorRecreateReason,
305	) -> Result<CoordinatorTmuxRecord> {
306	    let record = spawn
307	        .work_db
308	        .coordinator_tmux_record()?
309	        .ok_or_else(|| anyhow!("no coordinator tmux record exists"))?;
310	    if record.spawn_token != expected_spawn_token {
311	        bail!("coordinator changed before confirmation; refresh and confirm the current session instead");
312	    }
313	    if session_exists(spawn.tmux, &record.session_name).await? {
314	        match spawn
315	            .tmux
316	            .show_environment(&record.session_name, SPAWN_TOKEN_ENV)
317	            .await?
318	        {
319	            Some(token) if token == record.spawn_token => {
320	                spawn
321	                    .tmux
322	                    .kill_session_verified(&record.session_name, &record.spawn_token)
323	                    .await
324	                    .context("destroying the confirmed coordinator session")?;
325	            }
326	            Some(_) => bail!("coordinator tmux token does not match the metadata singleton"),
327	            None => bail!("coordinator tmux session exists without the metadata singleton token"),
328	        }
329	    }
330	    start_new(spawn, CoordinatorStartReason::Recreate(reason)).await
331	}
