333	async fn reconcile_existing(
334	    spawn: &CoordinatorSpawn<'_>,
335	    mut record: CoordinatorTmuxRecord,
336	) -> Result<CoordinatorTmuxRecord> {
337	    if !session_exists(spawn.tmux, &record.session_name).await? {
338	        // Covers both crash windows in which metadata was committed but
339	        // `new-session` never happened, and normal session loss. No live
340	        // conversation remains, so recreation is non-destructive.
341	        return start_new(spawn, CoordinatorStartReason::SessionMissing).await;
342	    }
343	    let live_token = spawn
344	        .tmux
345	        .show_environment(&record.session_name, SPAWN_TOKEN_ENV)
346	        .await?;
347	    match live_token {
348	        Some(token) if token == record.spawn_token => {
349	            crate::tmux_session_options::apply(spawn.tmux, &record.session_name)
350	                .await
351	                .context("applying Boss coordinator tmux session options")?;
352	            if spawn
353	                .tmux
354	                .display_message(&record.session_name, DisplayField::PaneDead)
355	                .await?
356	                .trim()
357	                == "1"
358	            {
359	                spawn
360	                    .tmux
361	                    .kill_session_verified(&record.session_name, &record.spawn_token)
362	                    .await
363	                    .context("removing dead coordinator tmux session before restart")?;
364	                return start_new(spawn, CoordinatorStartReason::PaneDead).await;
365	            }
366	            // Live matching-token sessions are left alone (including
367	            // model mismatches, which the app surfaces for confirmation).
368	            // An interrupted create still needs its token mirror repaired.
369	            if record.spawn_state == "intended" {
370	                confirm_existing_intent(spawn.work_db, spawn.tmux, &record).await?;
371	                record.spawn_state = "created".to_owned();
372	            }
373	            seed_claude_version_baseline_if_missing(spawn.work_db, &mut record, spawn.version_probe).await;
374	            // This branch is reached only when the engine is *adopting* a
375	            // session that already existed (outlived a prior process) —
376	            // as opposed to one just created by `start_new` above/below,
377	            // which already has the current prompt by construction.
378	            maybe_nudge_prompt_change(spawn.work_db, spawn.tmux, &record, spawn.working_directory).await;
379	            Ok(record)
380	        }
381	        Some(_) => bail!("coordinator tmux token does not match the metadata singleton"),
382	        None => bail!("coordinator tmux session exists without the metadata singleton token"),
383	    }
384	}
